import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.117.1';
import { CONFIG } from './config.js';

const configured = Boolean(CONFIG.SUPABASE_URL && CONFIG.SUPABASE_PUBLISHABLE_KEY);
const supabase = configured ? createClient(CONFIG.SUPABASE_URL, CONFIG.SUPABASE_PUBLISHABLE_KEY) : null;
const app = document.querySelector('#app');
const toastRoot = document.querySelector('#toast-root');
let currentPage = 'dashboard';
let user = null;
let profile = null;
let charts = [];
let cache = { estoque_products: [], inventory: [], estoque_categories: [], estoque_suppliers: [], movements: [], estoque_alerts: [], audits: [], batches: [], users: [], settings: null };

const demo = {
  estoque_categories:[{id:'c1',name:'Alimentos'},{id:'c2',name:'Bebidas'},{id:'c3',name:'Limpeza'}],
  estoque_suppliers:[{id:'s1',name:'Distribuidora Central',company:'DC Alimentos'},{id:'s2',name:'Atacado Nordeste',company:'Atacado Nordeste'}],
  estoque_products:[
    {id:'p1',internal_code:'AL-001',barcode:'789100000001',name:'Arroz 5kg',category_id:'c1',brand:'Boa Safra',unit:'UN',min_stock:20,max_stock:180,purchase_price:24.9,sale_price:31.9,location:'A-01-02',active:true},
    {id:'p2',internal_code:'BE-014',barcode:'789100000014',name:'Refrigerante 2L',category_id:'c2',brand:'Clássico',unit:'UN',min_stock:15,max_stock:120,purchase_price:6.5,sale_price:9.9,location:'B-02-01',active:true},
    {id:'p3',internal_code:'LI-021',barcode:'789100000021',name:'Detergente 500ml',category_id:'c3',brand:'Limp+',unit:'UN',min_stock:30,max_stock:200,purchase_price:1.9,sale_price:3.2,location:'C-01-04',active:true}
  ],
  inventory:[
    {product_id:'p1',quantity:96,reserved_quantity:0,last_entry_at:new Date(Date.now()-86400000*2).toISOString(),last_exit_at:new Date(Date.now()-86400000).toISOString()},
    {product_id:'p2',quantity:12,reserved_quantity:0,last_entry_at:new Date(Date.now()-86400000*4).toISOString(),last_exit_at:new Date().toISOString()},
    {product_id:'p3',quantity:0,reserved_quantity:0,last_entry_at:new Date(Date.now()-86400000*7).toISOString(),last_exit_at:new Date(Date.now()-86400000*2).toISOString()}
  ],
  movements:[
    {id:'m1',created_at:new Date().toISOString(),movement_type:'EXIT',quantity:8,previous_quantity:20,new_quantity:12,product_id:'p2',notes:'Saída para atendimento',destination:'Setor A',estoque_profiles:{full_name:'Administrador'}},
    {id:'m2',created_at:new Date(Date.now()-86400000).toISOString(),movement_type:'ENTRY',quantity:50,previous_quantity:46,new_quantity:96,product_id:'p1',notes:'Recebimento NF 1022',destination:null,estoque_profiles:{full_name:'Administrador'}},
    {id:'m3',created_at:new Date(Date.now()-86400000*2).toISOString(),movement_type:'EXIT',quantity:30,previous_quantity:30,new_quantity:0,product_id:'p3',notes:'Uso interno',destination:'Manutenção',estoque_profiles:{full_name:'Estoque'}},
  ],
  estoque_alerts:[]
};

const navItems = [
  ['dashboard','▦','Dashboard'],['inventory','◫','Estoque'],['estoque_products','□','Produtos'],['entry','＋','Entrada'],['exit','−','Saída'],['movements','↔','Movimentações'],['validity','◷','Validades'],['estoque_categories','▤','Categorias'],['estoque_suppliers','♙','Fornecedores'],['reports','▥','Relatórios'],['users','♟','Usuários'],['audit','◎','Auditoria'],['settings','⚙','Configurações']
];

function money(v){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0))}
function num(v){return new Intl.NumberFormat('pt-BR').format(Number(v||0))}
function dt(v){return v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—'}
function esc(v=''){return String(v).replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}
function toast(msg){toastRoot.innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>toastRoot.innerHTML='',2600)}
function categoryName(id){return cache.estoque_categories.find(x=>x.id===id)?.name||'Sem categoria'}
function productName(id){return cache.estoque_products.find(x=>x.id===id)?.name||'Produto'}
function estoque_stockFor(id){return cache.inventory.find(x=>x.product_id===id)?.quantity||0}
function estoque_stockStatus(p,q){if(q<=0)return ['SEM ESTOQUE','bad']; if(q<=Math.max(1,Math.floor((p.min_stock||0)*.5)))return ['CRÍTICO','bad']; if(q<=(p.min_stock||0))return ['ESTOQUE BAIXO','warn']; if(p.max_stock&&q>p.max_stock)return ['EXCESSO','info']; return ['NORMAL','ok']}
function destroyCharts(){charts.forEach(c=>c?.destroy?.());charts=[]}

async function start(){
  if(!configured){ user={id:'demo'}; profile={full_name:'Modo demonstração',role:'ADMIN'}; Object.assign(cache,structuredClone(demo)); renderShell(); renderPage(); return; }
  const { data:{session} } = await supabase.auth.getSession();
  if(!session){renderLogin();return}
  user=session.user; await loadProfile(); renderShell(); await refreshAll(); renderPage();
  supabase.auth.onAuthStateChange(async (_event,session)=>{if(!session){user=null;profile=null;renderLogin()}});
}

function renderLogin(){
 app.innerHTML=`<div class="login-shell"><div class="login-card"><div class="login-brand"><img src="data:image/webp;base64," class="login-brand-logo" alt="Estoque Pro"></div><h1>Entrar</h1><p>Acesse com seu usuário do Supabase Auth.</p><form id="login-form" class="stack"><div class="field"><label>E-mail</label><input name="email" type="email" required></div><div class="field"><label>Senha</label><input name="password" type="password" required></div><button class="btn primary">Entrar</button><button type="button" class="btn primary" id="signup-btn">Primeiro acesso? Criar conta agora</button><div class="login-help"><strong>Ainda não tem conta?</strong><br>Preencha e-mail e senha acima e clique em <b>Criar conta agora</b>. Não clique em Entrar no primeiro acesso.</div><small class="muted">O primeiro usuário cadastrado neste módulo recebe perfil ADMIN; os seguintes entram como visualizadores até serem promovidos.</small></form></div></div>`;
 document.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);const {data,error}=await supabase.auth.signInWithPassword({email:fd.get('email'),password:fd.get('password')});if(error){const msg=error.message==='Invalid login credentials'?'Conta não encontrada ou senha incorreta. Se esta é sua primeira vez, clique em CRIAR CONTA abaixo.':error.message;return toast(msg)}user=data.user;await loadProfile();renderShell();await refreshAll();renderPage()});
 document.querySelector('#signup-btn').onclick=async()=>{const form=document.querySelector('#login-form');const fd=new FormData(form);const email=String(fd.get('email')||'').trim();const password=String(fd.get('password')||'');if(!email||password.length<6)return toast('Informe e-mail e uma senha com pelo menos 6 caracteres.');const {data,error}=await supabase.auth.signUp({email,password,options:{data:{full_name:email.split('@')[0]}}});if(error)return toast(error.message);if(data.session){user=data.user;await loadProfile();renderShell();await refreshAll();renderPage();return}toast('Conta criada. Verifique seu e-mail para confirmar o cadastro.');};
}

async function loadProfile(){
 const {data,error}=await supabase.from('estoque_profiles').select('*').eq('id',user.id).single();
 if(error){profile={full_name:user.email,role:'VIEWER'};return} profile=data;
}

function renderShell(){
 app.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand sidebar-brand"><img src="data:image/webp;base64," class="sidebar-brand-logo" alt="Estoque Pro"><small>${configured?'Conectado ao Supabase':'Demonstração local'}</small></div><nav class="nav">${navItems.map(([id,ico,label])=>`<button data-page="${id}" class="${currentPage===id?'active':''}"><span>${ico}</span>${label}</button>`).join('')}</nav></aside><main class="main"><header class="topbar"><button class="icon-btn mobile-menu" id="menu-btn">☰</button><div class="search"><input id="global-search" placeholder="Buscar produto, código, código de barras, lote..."></div><div class="top-actions"><button class="icon-btn" id="theme-btn">◐</button><span class="muted" style="font-size:12px">${esc(profile?.full_name||'Usuário')} · ${esc(profile?.role||'VIEWER')}</span><button class="icon-btn" id="logout-btn">Sair</button></div></header><section class="content" id="content"></section></main></div>`;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{currentPage=b.dataset.page;document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===currentPage));renderPage();document.querySelector('#sidebar').classList.remove('open')});
 document.querySelector('#menu-btn').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');
 document.querySelector('#theme-btn').onclick=()=>{const d=document.documentElement;d.dataset.theme=d.dataset.theme==='dark'?'':'dark'};
 document.querySelector('#logout-btn').onclick=async()=>{if(!configured){location.reload();return}await supabase.auth.signOut();renderLogin()};
 document.querySelector('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){currentPage='estoque_products';renderPage(e.target.value)}});
}

async function refreshAll(){
 if(!configured)return;
 const [p,c,s,i,m,a,au,b,u,set]=await Promise.all([
  supabase.from('estoque_products').select('*').order('name'),
  supabase.from('estoque_categories').select('*').order('name'),
  supabase.from('estoque_suppliers').select('*').order('name'),
  supabase.from('estoque_stock').select('*'),
  supabase.from('estoque_stock_movements').select('*,estoque_profiles:performed_by(full_name)').order('created_at',{ascending:false}).limit(500),
  supabase.from('estoque_alerts').select('*').eq('resolved',false).order('created_at',{ascending:false}).limit(100),
  supabase.from('estoque_audit_logs').select('*,estoque_profiles:user_id(full_name)').order('created_at',{ascending:false}).limit(200),
  supabase.from('estoque_stock_batches').select('*').order('expires_at',{ascending:true}),
  supabase.from('estoque_profiles').select('*').order('created_at',{ascending:true}),
  supabase.from('estoque_settings').select('*').eq('id','main').maybeSingle()
 ]);
 cache.estoque_products=p.data||[];cache.estoque_categories=c.data||[];cache.estoque_suppliers=s.data||[];cache.inventory=i.data||[];cache.movements=m.data||[];cache.estoque_alerts=a.data||[];cache.audits=au.data||[];cache.batches=b.data||[];cache.users=u.data||[];cache.settings=set.data||null;
}

function pageHead(title,subtitle,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`}
function renderPage(search=''){destroyCharts();const c=document.querySelector('#content');if(!c)return;const pages={dashboard:renderDashboard,inventory:()=>renderInventory(search),estoque_products:()=>renderProducts(search),entry:()=>renderMovementForm('ENTRY'),exit:()=>renderMovementForm('EXIT'),movements:renderMovements,validity:renderValidity,estoque_categories:renderCategories,estoque_suppliers:renderSuppliers,reports:renderReports,users:renderUsers,audit:renderAudit,settings:renderSettings};(pages[currentPage]||renderDashboard)();}

function renderDashboard(){
 const c=document.querySelector('#content'); const totalUnits=cache.inventory.reduce((a,b)=>a+Number(b.quantity||0),0);const value=cache.estoque_products.reduce((a,p)=>a+(estoque_stockFor(p.id)*Number(p.purchase_price||0)),0);const low=cache.estoque_products.filter(p=>{const q=estoque_stockFor(p.id);return q>0&&q<=Number(p.min_stock||0)}).length;const zero=cache.estoque_products.filter(p=>estoque_stockFor(p.id)<=0).length;
 const today=new Date().toDateString();const todayMov=cache.movements.filter(m=>new Date(m.created_at).toDateString()===today);const entries=todayMov.filter(m=>m.movement_type==='ENTRY').reduce((a,m)=>a+Number(m.quantity),0);const exits=todayMov.filter(m=>m.movement_type==='EXIT').reduce((a,m)=>a+Number(m.quantity),0);
 c.innerHTML=pageHead('Dashboard','Visão rápida de entradas, saídas, saldo e alertas.',`<button class="btn primary" data-go="entry">+ Nova entrada</button><button class="btn" data-go="exit">− Nova saída</button>`)+`<div class="cards">${[['Produtos',cache.estoque_products.length],['Unidades disponíveis',totalUnits],['Entradas hoje',entries],['Saídas hoje',exits],['Estoque baixo',low],['Sem estoque',zero],['Valor estimado',money(value)],['Movimentações',cache.movements.length]].map(x=>`<div class="card metric"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="delta">Atualizado agora</div></div>`).join('')}</div><div class="quick-actions"><button class="btn" data-go="estoque_products">+ Novo produto</button><button class="btn" data-go="inventory">Consultar estoque</button><button class="btn" data-go="reports">Gerar relatório</button></div><div class="grid-2"><div class="card"><div class="kpi-row"><strong>Entradas x saídas</strong><span class="muted">Últimas movimentações</span></div><div class="chart-wrap"><canvas id="movement-chart"></canvas></div></div><div class="card"><strong>Distribuição por categoria</strong><div class="chart-wrap"><canvas id="category-chart"></canvas></div></div></div><div class="grid-2"><div class="card table-card"><div class="table-toolbar"><strong>Movimentações recentes</strong></div>${movementTable(cache.movements.slice(0,8))}</div><div class="card"><strong>Alertas</strong><div class="alert-list" style="margin-top:12px">${buildAlerts().slice(0,8).map(a=>`<div class="alert-item"><strong>${esc(a.title)}</strong><span class="muted">${esc(a.text)}</span></div>`).join('')||'<div class="empty">Nenhum alerta.</div>'}</div></div></div>`;
 c.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{currentPage=b.dataset.go;renderPage()});
 const labels=[...new Set(cache.movements.slice(0,40).map(m=>new Date(m.created_at).toLocaleDateString('pt-BR')).reverse())];const eData=labels.map(l=>cache.movements.filter(m=>new Date(m.created_at).toLocaleDateString('pt-BR')===l&&m.movement_type==='ENTRY').reduce((a,m)=>a+Number(m.quantity),0));const xData=labels.map(l=>cache.movements.filter(m=>new Date(m.created_at).toLocaleDateString('pt-BR')===l&&m.movement_type==='EXIT').reduce((a,m)=>a+Number(m.quantity),0));
 charts.push(new Chart(document.querySelector('#movement-chart'),{type:'bar',data:{labels,datasets:[{label:'Entradas',data:eData},{label:'Saídas',data:xData}]},options:{responsive:true,maintainAspectRatio:false}}));
 const cats=cache.estoque_categories.map(cat=>({name:cat.name,total:cache.estoque_products.filter(p=>p.category_id===cat.id).reduce((a,p)=>a+estoque_stockFor(p.id),0)})).filter(x=>x.total>0);charts.push(new Chart(document.querySelector('#category-chart'),{type:'doughnut',data:{labels:cats.map(x=>x.name),datasets:[{data:cats.map(x=>x.total)}]},options:{responsive:true,maintainAspectRatio:false}}));
}

function buildAlerts(){const arr=[];for(const p of cache.estoque_products){const q=estoque_stockFor(p.id);if(q<=0)arr.push({title:'Produto sem estoque',text:`${p.name} está esgotado.`});else if(q<=Number(p.min_stock||0))arr.push({title:'Estoque baixo',text:`${p.name} possui somente ${q} ${p.unit||'unidades'}.`});if(p.max_stock&&q>p.max_stock)arr.push({title:'Acima do limite',text:`${p.name} está acima do estoque máximo.`})}return [...arr,...cache.estoque_alerts.map(a=>({title:a.title,text:a.message}))]}

function renderInventory(search=''){
 const c=document.querySelector('#content');const q=search.toLowerCase();const rows=cache.estoque_products.filter(p=>!q||[p.name,p.internal_code,p.barcode,categoryName(p.category_id)].some(v=>String(v||'').toLowerCase().includes(q)));
 c.innerHTML=pageHead('Estoque atual','Saldo consolidado, limites e última movimentação.',`<button class="btn primary" id="adjust-inv">Inventário físico</button><button class="btn" id="export-inv">Exportar Excel</button>`)+`<div class="card table-card"><div class="table-toolbar"><input id="inv-search" placeholder="Buscar no estoque" value="${esc(search)}"><select id="status-filter"><option value="">Todos os status</option><option>NORMAL</option><option>ESTOQUE BAIXO</option><option>CRÍTICO</option><option>SEM ESTOQUE</option><option>EXCESSO</option></select></div><div class="table-wrap"><table id="inv-table"><thead><tr><th>Código</th><th>Produto</th><th>Categoria</th><th>Quantidade</th><th>Mín.</th><th>Máx.</th><th>Localização</th><th>Última entrada</th><th>Última saída</th><th>Status</th></tr></thead><tbody>${rows.map(p=>{const s=cache.inventory.find(x=>x.product_id===p.id)||{};const [label,cls]=estoque_stockStatus(p,Number(s.quantity||0));return `<tr data-status="${label}"><td>${esc(p.internal_code)}</td><td><strong>${esc(p.name)}</strong></td><td>${esc(categoryName(p.category_id))}</td><td>${num(s.quantity)}</td><td>${num(p.min_stock)}</td><td>${num(p.max_stock)}</td><td>${esc(p.location||'—')}</td><td>${dt(s.last_entry_at)}</td><td>${dt(s.last_exit_at)}</td><td><span class="badge ${cls}">${label}</span></td></tr>`}).join('')}</tbody></table></div></div>`;
 document.querySelector('#inv-search').oninput=e=>renderInventory(e.target.value);document.querySelector('#status-filter').onchange=e=>document.querySelectorAll('#inv-table tbody tr').forEach(r=>r.classList.toggle('hide',e.target.value&&r.dataset.status!==e.target.value));document.querySelector('#adjust-inv').onclick=()=>openAdjustModal();document.querySelector('#export-inv').onclick=()=>exportTable('inv-table','estoque-atual.xlsx');
}

function renderProducts(search=''){
 const c=document.querySelector('#content');const q=search.toLowerCase();const rows=cache.estoque_products.filter(p=>!q||[p.name,p.internal_code,p.barcode,p.brand].some(v=>String(v||'').toLowerCase().includes(q)));
 c.innerHTML=pageHead('Produtos','Cadastro central dos itens controlados.',`<button class="btn primary" id="new-product">+ Novo produto</button>`)+`<div class="card table-card"><div class="table-toolbar"><input id="product-search" placeholder="Buscar produto" value="${esc(search)}"></div><div class="table-wrap"><table><thead><tr><th>Código</th><th>Produto</th><th>Categoria</th><th>Marca</th><th>Un.</th><th>Estoque</th><th>Compra</th><th>Venda</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.internal_code)}</td><td><strong>${esc(p.name)}</strong><br><small class="muted">${esc(p.barcode||'')}</small></td><td>${esc(categoryName(p.category_id))}</td><td>${esc(p.brand||'—')}</td><td>${esc(p.unit||'UN')}</td><td>${num(estoque_stockFor(p.id))}</td><td>${money(p.purchase_price)}</td><td>${money(p.sale_price)}</td><td><span class="badge ${p.active===false?'neutral':'ok'}">${p.active===false?'INATIVO':'ATIVO'}</span></td><td><button class="btn ghost" data-edit="${p.id}">Editar</button></td></tr>`).join('')}</tbody></table></div></div>`;
 document.querySelector('#product-search').oninput=e=>renderProducts(e.target.value);document.querySelector('#new-product').onclick=()=>openProductModal();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openProductModal(cache.estoque_products.find(p=>p.id===b.dataset.edit)));
}

function openProductModal(p={}){if(profile?.role==='VIEWER')return toast('Seu perfil é somente leitura.');const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<form class="modal" id="product-form"><div class="modal-head"><strong>${p.id?'Editar':'Novo'} produto</strong><button type="button" class="icon-btn" data-close>✕</button></div><div class="modal-body"><div class="form-grid"><div class="field"><label>Código interno</label><input name="internal_code" required value="${esc(p.internal_code||'')}"></div><div class="field"><label>Código de barras</label><input name="barcode" value="${esc(p.barcode||'')}"></div><div class="field full"><label>Nome</label><input name="name" required value="${esc(p.name||'')}"></div><div class="field"><label>Categoria</label><select name="category_id"><option value="">Sem categoria</option>${cache.estoque_categories.map(x=>`<option value="${x.id}" ${x.id===p.category_id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Marca</label><input name="brand" value="${esc(p.brand||'')}"></div><div class="field"><label>Unidade</label><input name="unit" value="${esc(p.unit||'UN')}"></div><div class="field"><label>Localização</label><input name="location" value="${esc(p.location||'')}"></div><div class="field"><label>Estoque mínimo</label><input name="min_stock" type="number" min="0" value="${p.min_stock??0}"></div><div class="field"><label>Estoque máximo</label><input name="max_stock" type="number" min="0" value="${p.max_stock??0}"></div><div class="field"><label>Valor compra</label><input name="purchase_price" type="number" step="0.01" min="0" value="${p.purchase_price??0}"></div><div class="field"><label>Valor venda</label><input name="sale_price" type="number" step="0.01" min="0" value="${p.sale_price??0}"></div><div class="field full"><label>Descrição</label><textarea name="description">${esc(p.description||'')}</textarea></div></div></div><div class="modal-foot"><button type="button" class="btn" data-close>Cancelar</button><button class="btn primary">Salvar</button></div></form>`;document.body.appendChild(modal);modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.remove());modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target));const payload={...fd,category_id:fd.category_id||null,min_stock:Number(fd.min_stock||0),max_stock:Number(fd.max_stock||0),purchase_price:Number(fd.purchase_price||0),sale_price:Number(fd.sale_price||0),active:true};if(!configured){if(p.id)Object.assign(cache.estoque_products.find(x=>x.id===p.id),payload);else{payload.id='p'+Date.now();cache.estoque_products.push(payload);cache.inventory.push({product_id:payload.id,quantity:0})}modal.remove();renderProducts();toast('Produto salvo em modo demonstração.');return}const req=p.id?supabase.from('estoque_products').update(payload).eq('id',p.id):supabase.from('estoque_products').insert(payload).select().single();const {data,error}=await req;if(error)return toast(error.message);await refreshAll();modal.remove();renderProducts();toast('Produto salvo com sucesso.')}}

function renderMovementForm(type){const entry=type==='ENTRY';const c=document.querySelector('#content');c.innerHTML=pageHead(entry?'Entrada de estoque':'Saída de estoque',entry?'Registre o recebimento e atualize o saldo de forma atômica.':'Registre a retirada sem permitir saldo negativo.')+`<div class="card"><form id="movement-form"><div class="form-grid"><div class="field full"><label>Produto</label><select name="product_id" required><option value="">Selecione</option>${cache.estoque_products.map(p=>`<option value="${p.id}">${esc(p.internal_code)} — ${esc(p.name)} (saldo: ${estoque_stockFor(p.id)})</option>`).join('')}</select></div><div class="field"><label>Quantidade</label><input name="quantity" type="number" min="0.001" step="0.001" required></div><div class="field"><label>${entry?'Fornecedor':'Destino / setor'}</label>${entry?`<select name="supplier_id"><option value="">Não informado</option>${cache.estoque_suppliers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select>`:`<input name="destination" placeholder="Cliente, setor ou local">`}</div>${entry?`<div class="field"><label>Número da nota fiscal</label><input name="invoice_number"></div><div class="field"><label>Lote</label><input name="batch_code"></div><div class="field"><label>Validade</label><input name="expires_at" type="date"></div><div class="field"><label>Valor unitário</label><input name="unit_cost" type="number" step="0.01" min="0"></div>`:`<div class="field"><label>Motivo</label><select name="reason"><option>Venda</option><option>Uso interno</option><option>Transferência</option><option>Avaria</option><option>Perda</option><option>Vencimento</option><option>Devolução</option><option>Outro</option></select></div>`}<div class="field full"><label>Observações</label><textarea name="notes"></textarea></div></div><div class="actions" style="margin-top:16px"><button class="btn primary">${entry?'Confirmar entrada':'Confirmar saída'}</button></div></form></div>`;document.querySelector('#movement-form').onsubmit=e=>saveMovement(e,type);
}

async function saveMovement(e,type){e.preventDefault();if(profile?.role==='VIEWER')return toast('Seu perfil é somente leitura.');const fd=Object.fromEntries(new FormData(e.target));const qty=Number(fd.quantity);if(!qty||qty<=0)return toast('Informe uma quantidade válida.');if(!configured){const s=cache.inventory.find(x=>x.product_id===fd.product_id);const prev=Number(s.quantity||0);const next=type==='ENTRY'?prev+qty:prev-qty;if(next<0)return toast('Estoque insuficiente.');s.quantity=next;s[type==='ENTRY'?'last_entry_at':'last_exit_at']=new Date().toISOString();cache.movements.unshift({id:'m'+Date.now(),created_at:new Date().toISOString(),movement_type:type,quantity:qty,previous_quantity:prev,new_quantity:next,product_id:fd.product_id,notes:fd.notes,destination:fd.destination,estoque_profiles:{full_name:profile.full_name}});toast(`${qty} unidades ${type==='ENTRY'?'adicionadas':'retiradas'} do estoque.`);e.target.reset();return}
 const payload={p_product_id:fd.product_id,p_type:type,p_quantity:qty,p_supplier_id:fd.supplier_id||null,p_destination:fd.destination||null,p_reason:fd.reason||null,p_notes:fd.notes||null,p_invoice_number:fd.invoice_number||null,p_batch_code:fd.batch_code||null,p_expires_at:fd.expires_at||null,p_unit_cost:fd.unit_cost?Number(fd.unit_cost):null};const {error}=await supabase.rpc('estoque_move_stock',payload);if(error)return toast(error.message);await refreshAll();toast(`${qty} unidades ${type==='ENTRY'?'adicionadas':'retiradas'} do estoque.`);e.target.reset();}

function movementTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Qtd.</th><th>Saldo ant.</th><th>Saldo atual</th><th>Responsável</th><th>Destino/Fornecedor</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${dt(m.created_at)}</td><td>${esc(productName(m.product_id))}</td><td><span class="badge ${m.movement_type==='ENTRY'?'ok':m.movement_type==='EXIT'?'bad':'warn'}">${esc(m.movement_type)}</span></td><td>${num(m.quantity)}</td><td>${num(m.previous_quantity)}</td><td>${num(m.new_quantity)}</td><td>${esc(m.estoque_profiles?.full_name||'—')}</td><td>${esc(m.destination||'—')}</td></tr>`).join('')}</tbody></table></div>`}
function renderMovements(){const c=document.querySelector('#content');c.innerHTML=pageHead('Movimentações','Histórico permanente de entradas, saídas, ajustes e transferências.',`<button class="btn" id="export-mov">Exportar Excel</button>`)+`<div class="card table-card"><div class="table-toolbar"><select id="mov-type"><option value="">Todos os tipos</option><option value="ENTRY">ENTRADA</option><option value="EXIT">SAÍDA</option><option value="ADJUSTMENT">AJUSTE</option><option value="RETURN">DEVOLUÇÃO</option><option value="TRANSFER">TRANSFERÊNCIA</option></select><input id="mov-search" placeholder="Buscar produto"></div><div id="mov-table">${movementTable(cache.movements)}</div></div>`;const apply=()=>{const t=document.querySelector('#mov-type').value;const q=document.querySelector('#mov-search').value.toLowerCase();const rows=cache.movements.filter(m=>(!t||m.movement_type===t)&&(!q||productName(m.product_id).toLowerCase().includes(q)));document.querySelector('#mov-table').innerHTML=movementTable(rows)};document.querySelector('#mov-type').onchange=apply;document.querySelector('#mov-search').oninput=apply;document.querySelector('#export-mov').onclick=()=>exportRows(cache.movements.map(m=>({Data:dt(m.created_at),Produto:productName(m.product_id),Tipo:m.movement_type,Quantidade:m.quantity,'Saldo anterior':m.previous_quantity,'Saldo atual':m.new_quantity,Responsável:m.estoque_profiles?.full_name||'',Destino:m.destination||''})),'movimentacoes.xlsx')}

function renderValidity(){const c=document.querySelector('#content');const batches=cache.batches.map(b=>({product:productName(b.product_id),batch:b.batch_code,expires_at:b.expires_at,quantity:b.quantity})).filter(b=>b.expires_at);c.innerHTML=pageHead('Validades','Controle de lotes e produtos próximos do vencimento.')+`<div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Lote</th><th>Quantidade</th><th>Validade</th><th>Dias restantes</th><th>Status</th></tr></thead><tbody>${batches.map(b=>{const days=Math.ceil((new Date(b.expires_at)-new Date())/86400000);const st=days<0?['VENCIDO','bad']:days<7?['VERMELHO','bad']:days<15?['LARANJA','warn']:days<=30?['AMARELO','warn']:['VERDE','ok'];return `<tr><td>${esc(b.product)}</td><td>${esc(b.batch||'—')}</td><td>${num(b.quantity)}</td><td>${new Date(b.expires_at).toLocaleDateString('pt-BR')}</td><td>${days}</td><td><span class="badge ${st[1]}">${st[0]}</span></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Nenhum lote com validade registrado nas movimentações carregadas.</td></tr>'}</tbody></table></div></div>`}

function simpleListPage(kind){const isCat=kind==='estoque_categories';const rows=isCat?cache.estoque_categories:cache.estoque_suppliers;const title=isCat?'Categorias':'Fornecedores';const c=document.querySelector('#content');c.innerHTML=pageHead(title,isCat?'Organize os produtos em grupos personalizados.':'Cadastre fornecedores e consulte a base de parceiros.',`<button class="btn primary" id="new-simple">+ Novo</button>`)+`<div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Nome</th>${isCat?'':'<th>Empresa</th><th>CNPJ</th><th>WhatsApp</th><th>E-mail</th>'}<th>Ações</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td>${isCat?'':`<td>${esc(r.company||'—')}</td><td>${esc(r.cnpj||'—')}</td><td>${esc(r.whatsapp||'—')}</td><td>${esc(r.email||'—')}</td>`}<td><button class="btn ghost" data-edit-simple="${r.id}">Editar</button></td></tr>`).join('')}</tbody></table></div></div>`;document.querySelector('#new-simple').onclick=()=>openSimpleModal(kind);document.querySelectorAll('[data-edit-simple]').forEach(b=>b.onclick=()=>openSimpleModal(kind,rows.find(x=>x.id===b.dataset.editSimple)))}
function renderCategories(){simpleListPage('estoque_categories')}function renderSuppliers(){simpleListPage('estoque_suppliers')}
function openSimpleModal(kind,item={}){if(profile?.role==='VIEWER')return toast('Seu perfil é somente leitura.');const isCat=kind==='estoque_categories';const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<form class="modal"><div class="modal-head"><strong>${item.id?'Editar':'Novo'} ${isCat?'categoria':'fornecedor'}</strong><button type="button" class="icon-btn" data-close>✕</button></div><div class="modal-body"><div class="form-grid"><div class="field full"><label>Nome</label><input name="name" required value="${esc(item.name||'')}"></div>${isCat?'':`<div class="field"><label>Empresa</label><input name="company" value="${esc(item.company||'')}"></div><div class="field"><label>CNPJ</label><input name="cnpj" value="${esc(item.cnpj||'')}"></div><div class="field"><label>WhatsApp</label><input name="whatsapp" value="${esc(item.whatsapp||'')}"></div><div class="field"><label>E-mail</label><input name="email" type="email" value="${esc(item.email||'')}"></div><div class="field full"><label>Endereço</label><input name="address" value="${esc(item.address||'')}"></div>`}</div></div><div class="modal-foot"><button type="button" class="btn" data-close>Cancelar</button><button class="btn primary">Salvar</button></div></form>`;document.body.appendChild(m);m.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>m.remove());m.querySelector('form').onsubmit=async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.target));if(!configured){const arr=isCat?cache.estoque_categories:cache.estoque_suppliers;if(item.id)Object.assign(arr.find(x=>x.id===item.id),payload);else arr.push({id:'x'+Date.now(),...payload});m.remove();simpleListPage(kind);return}const req=item.id?supabase.from(kind).update(payload).eq('id',item.id):supabase.from(kind).insert(payload);const {error}=await req;if(error)return toast(error.message);await refreshAll();m.remove();simpleListPage(kind);toast('Registro salvo.')}}

function openAdjustModal(){
 if(profile?.role==='VIEWER')return toast('Seu perfil é somente leitura.');
 const m=document.createElement('div');m.className='modal-backdrop';
 m.innerHTML=`<form class="modal"><div class="modal-head"><strong>Inventário físico</strong><button type="button" class="icon-btn" data-close>✕</button></div><div class="modal-body"><div class="form-grid"><div class="field full"><label>Produto</label><select name="product_id" required><option value="">Selecione</option>${cache.estoque_products.map(p=>`<option value="${p.id}">${esc(p.internal_code)} — ${esc(p.name)} (sistema: ${estoque_stockFor(p.id)})</option>`).join('')}</select></div><div class="field"><label>Quantidade física encontrada</label><input name="physical_quantity" type="number" min="0" step="0.001" required></div><div class="field full"><label>Justificativa</label><textarea name="justification" required placeholder="Ex.: contagem física do inventário mensal"></textarea></div></div></div><div class="modal-foot"><button type="button" class="btn" data-close>Cancelar</button><button class="btn primary">Confirmar ajuste</button></div></form>`;
 document.body.appendChild(m);m.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>m.remove());
 m.querySelector('form').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target));const physical=Number(fd.physical_quantity);if(!configured){const st=cache.inventory.find(x=>x.product_id===fd.product_id);const prev=Number(st.quantity||0);st.quantity=physical;const diff=physical-prev;if(diff!==0)cache.movements.unshift({id:'m'+Date.now(),created_at:new Date().toISOString(),movement_type:'ADJUSTMENT',quantity:Math.abs(diff),previous_quantity:prev,new_quantity:physical,product_id:fd.product_id,notes:fd.justification,estoque_profiles:{full_name:profile.full_name}});m.remove();renderInventory();toast('Inventário ajustado no modo demonstração.');return}const {error}=await supabase.rpc('estoque_adjust_inventory',{p_product_id:fd.product_id,p_physical_quantity:physical,p_justification:fd.justification});if(error)return toast(error.message);await refreshAll();m.remove();renderInventory();toast('Ajuste de inventário registrado com histórico.');};
}

function renderReports(){const c=document.querySelector('#content');const reportCards=[['Estoque atual','Saldo por produto e categoria','inventory'],['Entradas e saídas','Histórico de movimentações','movements'],['Estoque baixo','Itens que precisam reposição','inventory'],['Validades','Lotes próximos do vencimento','validity'],['Valor financeiro','Valor de compra do estoque','inventory'],['Por funcionário','Movimentações por responsável','movements']];c.innerHTML=pageHead('Relatórios','Central de relatórios operacionais e financeiros.')+`<div class="grid-3">${reportCards.map(r=>`<div class="card"><strong>${r[0]}</strong><p class="muted">${r[1]}</p><button class="btn" data-report="${r[2]}">Abrir relatório</button></div>`).join('')}</div><div class="card" style="margin-top:14px"><strong>Exportação</strong><p class="muted">As tabelas possuem exportação para Excel. Para PDF, use o botão abaixo e escolha “Salvar como PDF” na impressão do navegador.</p><button class="btn" id="print-report">Gerar PDF / Imprimir</button></div>`;document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{currentPage=b.dataset.report;renderPage()});document.querySelector('#print-report').onclick=()=>window.print()}
function renderUsers(){const c=document.querySelector('#content');const rows=cache.users.map(u=>`<tr><td>${esc(u.full_name||'—')}</td><td><span class="badge ${u.role==='ADMIN'?'bad':u.role==='STOCKER'?'info':'neutral'}">${esc(u.role)}</span></td><td>${u.active?'Ativo':'Inativo'}</td><td>${dt(u.created_at)}</td></tr>`).join('');c.innerHTML=pageHead('Usuários e permissões','Perfis persistidos no Supabase Auth e vinculados ao módulo de estoque.')+`<div class="card"><h3>Níveis de acesso</h3><div class="grid-3"><div><span class="badge bad">ADMIN</span><p class="muted">Cadastro, edição, estoque, usuários, relatórios e configurações.</p></div><div><span class="badge info">STOCKER</span><p class="muted">Entradas, saídas, consulta de estoque e movimentações.</p></div><div><span class="badge neutral">VIEWER</span><p class="muted">Somente leitura de estoque e relatórios.</p></div></div></div><div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Usuário</th><th>Perfil</th><th>Status</th><th>Criado em</th></tr></thead><tbody>${rows||'<tr><td colspan="4" class="empty">Nenhum usuário cadastrado ainda.</td></tr>'}</tbody></table></div></div>`}
function renderAudit(){const c=document.querySelector('#content');c.innerHTML=pageHead('Auditoria','Registro de alterações relevantes. Logs não devem ser apagados pela aplicação.')+`<div class="card table-card"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Usuário</th><th>Ação</th><th>Entidade</th><th>Registro</th><th>Antes</th><th>Depois</th></tr></thead><tbody>${cache.audits.map(a=>`<tr><td>${dt(a.created_at)}</td><td>${esc(a.estoque_profiles?.full_name||'—')}</td><td>${esc(a.action)}</td><td>${esc(a.entity)}</td><td>${esc(a.record_id||'—')}</td><td><small>${esc(JSON.stringify(a.before_data||{})).slice(0,90)}</small></td><td><small>${esc(JSON.stringify(a.after_data||{})).slice(0,90)}</small></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nenhum evento carregado.</td></tr>'}</tbody></table></div></div>`}
function renderSettings(){const c=document.querySelector('#content');c.innerHTML=pageHead('Configurações','Status do ambiente e segurança.')+`<div class="grid-2"><div class="card"><h3>Conexão</h3><p><b>Modo:</b> ${configured?'Supabase real':'Demonstração local'}</p><p><b>URL:</b> ${configured?esc(CONFIG.SUPABASE_URL):'Não configurada'}</p><p class="muted">Use somente chave publicável no frontend. Nunca coloque service_role/secret key em config.js.</p></div><div class="card"><h3>Segurança</h3><p>RLS: definido no arquivo <code>supabase/schema.sql</code>.</p><p>Perfis: ADMIN, STOCKER e VIEWER.</p><p>Movimentações: RPC atômica <code>estoque_move_stock</code>.</p></div></div>`}

function exportRows(rows,filename){const ws=XLSX.utils.json_to_sheet(rows);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Relatório');XLSX.writeFile(wb,filename)}
function exportTable(id,filename){const table=document.getElementById(id);const wb=XLSX.utils.table_to_book(table,{sheet:'Estoque'});XLSX.writeFile(wb,filename)}

start();